function dispatch(target, log) {
  const path = [];
  for (let node = target; node; node = node.parent) path.push(node);
  let stopped = false;
  for (const node of path) {
    if (stopped) break;
    if (node.onclick) node.onclick({ target, stop: () => (stopped = true) });
    log.push(node.name);
  }
}
