class Cart extends EventTarget {
  #lines = new Map();

  add(sku, qty) {
    this.#lines.set(sku, (this.#lines.get(sku) ?? 0) + qty);
    let count = 0;
    for (const n of this.#lines.values()) count += n;
    this.dispatchEvent(new CustomEvent("change", { detail: { sku, qty: this.#lines.get(sku), count } }));
  }
}

