function closestWith(node, key) {
  for (let n = node; n; n = n.parent) {
    if (n.data && key in n.data) return n;
  }
  return null;
}

function handleClick(target) {
  const button = closestWith(target, "action");
  if (!button) return "ignored";
  const line = closestWith(button, "sku");
  return `${button.data.action} ${line.data.sku}`;
}

