function parseQuantity(text) {
  const t = text.trim();
  if (!/^[0-9]+$/.test(t)) return { error: "Enter a whole number" };
  const qty = Number(t);
  if (qty < 1 || qty > 20) return { error: "Choose 1 to 20" };
  return { qty };
}

for (const text of [" 3 ", "20", "21", "0", "-2", "2.5", "abc", ""]) {
  console.log(JSON.stringify(text), parseQuantity(text));
}

