function collect(fields) {
  const data = {};
  for (const field of fields) {
    if (!field.name) continue;
    if (field.type === "checkbox") {
      if (field.checked) data[field.name] = String(field.value ?? "on");
      continue;
    }
    data[field.name] = String(field.value);
  }
  return data;
}

